#include <iostream>
#include <vector>
#include <iomanip>

void printPass(const std::vector<int>& arr, unsigned int pass, size_t insertIndex) {
    std::cout << "After pass " << std::setw(2) << pass << ": ";
    for (size_t i = 0; i < insertIndex; ++i) {
        std::cout << arr[i] << "  ";
    }
    std::cout << arr[insertIndex] << "* ";
    for (size_t i = insertIndex + 1; i < arr.size(); ++i) {
        std::cout << arr[i] << "  ";
    }
    std::cout << "\n               ";
    for (size_t i = 0; i <= pass; ++i) {
        std::cout << "--  ";
    }
    std::cout << "\n";
}

void insertionSort(std::vector<int>& arr) {
    for (size_t i = 1; i < arr.size(); ++i) {
        int insert = arr[i];
        size_t moveItem = i;
        while (moveItem > 0 && arr[moveItem - 1] > insert) {
            arr[moveItem] = arr[moveItem - 1];
            --moveItem;
        }
        arr[moveItem] = insert;
        printPass(arr, static_cast<unsigned int>(i), moveItem);
    }
}

int main() {
    std::vector<int> data = {72, 16, 11, 92, 63, 99, 59, 82, 99, 30};

    std::cout << "Unsorted array:\n";
    for (int val : data) {
        std::cout << val << "  ";
    }
    std::cout << "\n\n";

    insertionSort(data);

    std::cout << "Sorted array:\n";
    for (int val : data) {
        std::cout << val << "  ";
    }
    std::cout << "\n";
    return 0;
}

#include <iostream>
#include <vector>

void displaySubArray(const std::vector<int>& arr, size_t left, size_t right) {
    for (size_t i = 0; i < left; ++i) {
        std::cout << "   ";
    }
    for (size_t i = left; i <= right; ++i) {
        std::cout << " " << arr[i];
    }
}

void merge(std::vector<int>& arr, std::vector<int>& temp, size_t left, size_t middle1, size_t middle2, size_t right) {
    size_t leftIndex = left;
    size_t rightIndex = middle2;
    size_t combinedIndex = left;

    while (leftIndex <= middle1 && rightIndex <= right) {
        if (arr[leftIndex] <= arr[rightIndex]) {
            temp[combinedIndex++] = arr[leftIndex++];
        } else {
            temp[combinedIndex++] = arr[rightIndex++];
        }
    }

    if (leftIndex == middle2) {
        while (rightIndex <= right) {
            temp[combinedIndex++] = arr[rightIndex++];
        }
    } else {
        while (leftIndex <= middle1) {
            temp[combinedIndex++] = arr[leftIndex++];
        }
    }

    for (size_t i = left; i <= right; ++i) {
        arr[i] = temp[i];
    }
}

void sortSubArray(std::vector<int>& arr, std::vector<int>& temp, size_t low, size_t high) {
    if (high > low) {
        size_t middle1 = (low + high) / 2;
        size_t middle2 = middle1 + 1;

        sortSubArray(arr, temp, low, middle1);
        sortSubArray(arr, temp, middle2, high);
        merge(arr, temp, low, middle1, middle2, high);
    }
}

void mergeSort(std::vector<int>& arr) {
    if (arr.empty()) return;
    std::vector<int> temp(arr.size());
    sortSubArray(arr, temp, 0, arr.size() - 1);
}

int main() {
    std::vector<int> data = {4, 10, 34, 56, 77, 5, 30, 51, 52, 93};

    std::cout << "Original array:\n";
    for (int val : data) {
        std::cout << val << " ";
    }
    std::cout << "\n";

    // Test merge logic on two pre-sorted halves: [0..4] and [5..9]
    std::vector<int> temp(data.size());
    merge(data, temp, 0, 4, 5, 9);

    std::cout << "After merging two sorted halves:\n";
    for (int val : data) {
        std::cout << val << " ";
    }
    std::cout << "\n";
    return 0;
}
